def allow_bind(self, source: str, *, rebind: bool = False, now: float | None = None) -> bool:
    """Bound relay-bind attempts per transport source.

    Dead-session reconnects are exempt so recovery is not delayed.  The
    source is used only as an in-memory key and is never written to logs.
    """
    if rebind or self._bind_rate_limit == 0:
        return True
    current = time.monotonic() if now is None else now
    with self._lock:
        start, count = self._bind_rate_buckets.get(source, (current, 0))
        if current - start >= RELAY_BIND_RATE_WINDOW_S:
            start, count = current, 0
        count += 1
        self._bind_rate_buckets[source] = (start, count)
        if len(self._bind_rate_buckets) > 4096:
            self._bind_rate_buckets = {
                key: bucket
                for key, bucket in self._bind_rate_buckets.items()
                if current - bucket[0] < RELAY_BIND_RATE_WINDOW_S
            }
        return count <= self._bind_rate_limit

allowBind(source: string, opts: { rebind?: boolean; now?: number } = {}): boolean {
  if (opts.rebind || this._bindRateLimit === 0) return true;
  const now = opts.now ?? Date.now();
  let bucket = this._bindRateBuckets.get(source);
  if (!bucket || now - bucket.start >= RELAY_BIND_RATE_WINDOW_MS) bucket = { start: now, count: 0 };
  bucket.count += 1;
  this._bindRateBuckets.set(source, bucket);
  if (this._bindRateBuckets.size > 4096) {
    const cutoff = now - RELAY_BIND_RATE_WINDOW_MS;
    for (const [key, value] of this._bindRateBuckets) {
      if (value.start < cutoff) this._bindRateBuckets.delete(key);
    }
  }
  return bucket.count <= this._bindRateLimit;
}

pub fn allow_bind(&self, source: &str, rebind: bool, now: Instant) -> bool {
    if rebind || self.bind_rate_limit == 0 {
        return true;
    }
    let mut buckets = self.bind_rate_buckets.lock().unwrap();
    let entry = buckets.entry(source.to_string()).or_insert((now, 0));
    if now.duration_since(entry.0) >= RELAY_BIND_RATE_WINDOW {
        *entry = (now, 0);
    }
    entry.1 += 1;
    let allowed = entry.1 <= self.bind_rate_limit;
    if buckets.len() > 4096 {
        buckets.retain(|_, (start, _)| now.duration_since(*start) < RELAY_BIND_RATE_WINDOW);
    }
    allowed
}

pub(crate) fn register_rate_step(prev: Option<(u32, u64)>, now_ms: u64, ttl_ms: u64) -> (u32, u64) {
    match prev {
        Some((count, start_ms)) if now_ms.saturating_sub(start_ms) < ttl_ms => {
            (count + 1, start_ms)
        }
        _ => (1, now_ms),
    }
}
